  },
  {
   "id": "FAM:SF-TMP-009",
   "status_as_recorded": "artifact",
   "finding": "The PULL_UP-specific decline with exposure is defensive adaptation rather than shooter selection/lineup artifact. With lineup FE: slope holding shot fixed -0.0255 (0.0061); shooter's earlier scored -0.1044 vs not scored +0.0693. No lineup FE: -0.0063 (0.0036); placebo other play types -0.0075 (0.0017)."
  },
  {
   "id": "FAM:SF34",
   "status_as_recorded": "inconclusive",
   "finding": "Offenses attack the rim more when the opponent has no big on the floor. [CHT-075] DRIVE +0.82pp (SE 0.25 t=+3.3); POST_UP +0.43pp (SE 0.18 t=+2.4); 3PA -1.79pp (SE 0.31 t=-5.8); rim <=4ft +0.12pp (t=+0.4); PPP +0.008 (SE 0.007 t=+1.1). [TMP-020] rim_pct 0 bigs +0.123 (SE 0.295); tpa_pct -1.785 (SE 0.309); is_DRIVE +0.821 (SE 0.250); pts +0.008 (SE 0.007)."
  }
 ],
 "failed_approaches": [
  {
   "id": "FAM:SF-CHT-029",
   "what_failed": "Attempting to isolate play-type memory effects without adequate control for team quality and within-team baseline.",
